// 1. Ref as prop (Không cần forwardRef):
function CustomInput({ placeholder, ref }: { placeholder: string; ref: React.Ref<HTMLInputElement> }) {
  return <input ref={ref} placeholder={placeholder} />;
}

// 2. use() trong câu lệnh if:
function ConditionalTheme({ isDark }: { isDark: boolean }) {
  if (!isDark) return <div>Light</div>;
  const theme = use(ThemeContext); // ✅ Hợp lệ trong React!
  return <div>{theme.accent}</div>;
}

function UserProfile({ userPromise, shouldShowTheme }: Props) {
  // 1. Unwrap Promise với Suspense tự động:
  const user = use(userPromise);

  // 2. Đọc Context có điều kiện bên trong if:
  let theme = 'default';
  if (shouldShowTheme) {
    theme = use(ThemeContext);
  }

  return <div className={theme}>{user.name}</div>;
}

import { useFormStatus } from 'react-dom';

function SubmitButton() {
  const { pending } = useFormStatus();
  return (
    <button type="submit" disabled={pending}>
      {pending ? 'Đang lưu...' : 'Lưu thay đổi'}
    </button>
  );
}

// Trong Form cha:
function ProfileForm() {
  return (
    <form action={updateProfileAction}>
      <input name="username" />
      <SubmitButton /> {/* Tự động đọc pending từ form cha */}
    </form>
  );
}

// action.ts
'use server';
export async function updateEmail(prevState: any, formData: FormData) {
  const email = formData.get('email');
  if (!email) return { error: 'Email không được để trống' };
  return { success: true };
}

// component.tsx
function EmailForm() {
  const [state, formAction, isPending] = useActionState(updateEmail, null);
  return (
    <form action={formAction}>
      <input name="email" />
      {state?.error && <p className="text-red-500">{state.error}</p>}
      <button disabled={isPending}>{isPending ? 'Đang gửi...' : 'Cập nhật'}</button>
    </form>
  );
}

function DeletePostButton({ postId }: { postId: string }) {
  const [isPending, startTransition] = useTransition();

  const handleDelete = () => {
    startTransition(async () => {
      // Hỗ trợ async/await trực tiếp trong React 19!
      await deletePostServerAction(postId);
      toast.success('Đã xóa bài viết');
    });
  };

  return (
    <button onClick={handleDelete} disabled={isPending}>
      {isPending ? 'Đang xóa...' : 'Xóa bài'}
    </button>
  );
}

